const produk: string[] = ['Baju', 'Celana', 'Sepatu'];

// ✅ Push string — boleh
produk.push('Topi');

// ❌ Push number — tidak boleh
produk.push(42);
// Error: Argument of type 'number' is not assignable to
//        parameter of type 'string'

// ✅ map, filter, reduce juga terjaga tipenya
const hurufBesar = produk.map(p => p.toUpperCase());
// hurufBesar bertipe string[] — TS tahu ini

const panjang = produk.map(p => p.length);
// panjang bertipe number[] — TS tahu .length return number

