const keranjang: Produk[] = [
  { id: 1, nama: 'Kaos', harga: 75000 },
  { id: 2, nama: 'Celana', harga: 150000 },
];

// TS tahu properti apa yang tersedia saat iterasi
const total = keranjang.reduce((sum, item) => sum + item.harga, 0);
// item.harga ✅ — TS tahu 'harga' ada di Produk
