// Bisa kasih nama untuk tiap posisi (TS 4.0+)
// Nama tidak mempengaruhi perilaku, hanya dokumentasi
type Koordinat = [lat: number, lng: number];
type RentangTanggal = [mulai: Date, selesai: Date];

