// Saat hover di editor, kamu lihat nama parameternya — lebih jelas

// Pakai ARRAY saat:
// - Jumlah elemen tidak tetap
// - Semua elemen tipenya sama
const nilaiUjian: number[] = [90, 85, 92, 78, 95];

// Pakai TUPLE saat:
// - Jumlah elemen tetap dan sudah diketahui
// - Tiap posisi punya makna berbeda
// Contoh nyata: return dari fungsi yang return 2 nilai
function getMinMax(angka: number[]): [number, number] {
  return [Math.min(...angka), Math.max(...angka)];
}

const [min, max] = getMinMax([5, 2, 8, 1, 9]);
