type Profil = {
  nama: string;         // wajib
  email: string;        // wajib
  telepon?: string;     // opsional
  bio?: string;         // opsional
  fotoUrl?: string;     // opsional
};

// ✅ Hanya isi yang wajib
const profil1: Profil = {
  nama: 'Budi',
  email: 'budi@mail.com'
};

// ✅ Isi sebagian opsional
const profil2: Profil = {
  nama: 'Ani',
  email: 'ani@mail.com',
  telepon: '081234567890'
};

// ✅ Isi semua
const profil3: Profil = {
  nama: 'Cici',
  email: 'cici@mail.com',
  telepon: '089876543210',
  bio: 'Developer dari Bandung',
  fotoUrl: 'https://cdn.example.com/cici.jpg'
};

function tampilkanProfil(profil: Profil) {
  console.log(profil.nama);
  console.log(profil.email);

  // ❌ Langsung akses tanpa cek — bisa undefined
  console.log(profil.telepon.toUpperCase());
  // Error: Object is possibly 'undefined'

  // ✅ Cara 1: if check
  if (profil.telepon) {
    console.log(profil.telepon.toUpperCase());
  }

  // ✅ Cara 2: optional chaining (?.) 
  console.log(profil.telepon?.toUpperCase());
  // Kalau telepon undefined, hasilnya undefined (tidak error)

  // ✅ Cara 3: nullish coalescing (??)
  console.log(profil.bio ?? 'Belum ada bio');
  // Kalau bio undefined, tampilkan 'Belum ada bio'
}

// Parameter opsional juga pakai ?
function buat Salam(nama: string, sapaan?: string): string {
  // sapaan bisa undefined, jadi kita beri default
  const awalan = sapaan ?? 'Halo';
  return `${awalan}, ${nama}!`;
}

buatSalam('Budi');            // 'Halo, Budi!'
buatSalam('Ani', 'Selamat pagi');  // 'Selamat pagi, Ani!'

