type User = {
  readonly id: number;      // tidak boleh diubah
  readonly createdAt: Date; // tidak boleh diubah
  nama: string;             // boleh diubah
  email: string;            // boleh diubah
};

const user: User = {
  id: 1,
  createdAt: new Date(),
  nama: 'Budi',
  email: 'budi@mail.com'
};

// ✅ Ubah property biasa
user.nama = 'Budi Santoso';
user.email = 'budi.santoso@mail.com';

// ❌ Ubah readonly — tidak boleh!
user.id = 2;
// Error: Cannot assign to 'id' because it is a read-only property
user.createdAt = new Date();
// Error: Cannot assign to 'createdAt' because it is a read-only property

