// const: untuk VARIABEL — referensinya tidak bisa diubah
const user = { nama: 'Budi', umur: 25 };
user = { nama: 'Ani', umur: 22 }; // ❌ Error: tidak bisa reassign const
user.nama = 'Andi'; // ✅ Tapi isinya masih bisa diubah!

// readonly: untuk PROPERTY dalam objek/interface
// Melindungi property dari perubahan
type User = { readonly nama: string; umur: number };
const u: User = { nama: 'Budi', umur: 25 };
u.nama = 'Andi'; // ❌ Error: readonly property
u.umur = 26;     // ✅ Boleh

// Singkatnya:
// const = lock pada variabelnya (tidak bisa reassign)
// readonly = lock pada property objeknya (tidak bisa diubah isinya)
